/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import re
p=Path('.')
ips={i:re.search(r'inet (\\d+\\.\\d+\\.\\d+\\.\\d+)/',Path(f'pc{i}.startup').read_text()).group(1) for i in range(1,61)}
zones={'com':3,'net':4,'edu':5,'it':6,'org':8,'io':9,'gov':10,'info':12}
hosts={'open.ministero.gov':46,'servizi.ministero.gov':47,'shop.example.com':16,'ai.research.lab.net':22,'data.research.lab.net':23,'api.startup.io':44,'studenti.unibo.it':29,'blog.example.com':17,'ci.tools.net':25,'archive.foundation.org':42,'docs.project.org':43,'dept.company.com':18,'intranet.company.com':19,'local.news.info':48,'media.news.info':49,'api.service.com':20,'status.platform.io':45,'vpn.university.edu':26,'courses.university.edu':27,'portal.campus.edu':28,'dev.lab.net':24,'servizi.comune.it':30,'dati.regione.it':31,'mail.company.com':7,'mail.university.edu':11,'mail.dept.company.com':18,'mail.servizi.ministero.gov':47}
mx={'company.com':'mail.company.com','university.edu':'mail.university.edu','dept.company.com':'mail.dept.company.com','servizi.ministero.gov':'mail.servizi.ministero.gov'}
conf=Path('lab.conf').read_text()
servers={1,2,*zones.values()}
for i in servers:
 conf=conf.replace(f'pc{i}[image]=\"kathara/base\"',f'pc{i}[image]=\"kathara/bind\"')
Path('lab.conf').write_text(conf)
auth='options { directory \"/var/cache/bind\"; recursion no; allow-query { any; }; dnssec-validation no; listen-on { any; }; listen-on-v6 { any; }; };\\n'
def write(dev,name,content):
 d=Path(f'pc{dev}/etc/bind'); d.mkdir(parents=True,exist_ok=True); (d/name).write_text(content)
write(1,'named.conf',auth+'zone \".\" { type master; file \"/etc/bind/db.root\"; };\\n')
root='"'$TTL 3600'"\\n@ IN SOA a.root-servers. hostmaster.root-servers. ( 1 3600 900 604800 300 )\\n@ IN NS a.root-servers.\\na.root-servers. IN A '+ips[1]+'\\n'
for z,i in zones.items(): root+=f'{z}. IN NS ns.{z}.\\nns.{z}. IN A {ips[i]}\\n'
write(1,'db.root',root)
write(2,'named.conf','options { directory \"/var/cache/bind\"; recursion yes; allow-recursion { any; }; allow-query { any; }; dnssec-validation no; listen-on { any; }; listen-on-v6 { any; }; };\\nzone \".\" { type hint; file \"/etc/bind/db.hints\"; };\\n')
write(2,'db.hints',f'. 3600000 IN NS a.root-servers.\\na.root-servers. 3600000 IN A {ips[1]}\\n')
for z,i in zones.items():
 write(i,'named.conf',auth+f'zone \"{z}\" {{ type master; file \"/etc/bind/db.{z}\"; }};\\n')
 data=f'"'$TTL 3600'"\\n@ IN SOA ns.{z}. hostmaster.{z}. ( 1 3600 900 604800 300 )\\n@ IN NS ns.{z}.\\nns IN A {ips[i]}\\n'
 for name,n in hosts.items():
  if name.endswith('.'+z): data+=f'{name}. IN A {ips[n]}\\n'
 for name,target in mx.items():
  if name.endswith('.'+z): data+=f'{name}. IN MX 10 {target}.\\n'
 write(i,'db.'+z,data)
for f in list(p.glob('pc*.startup'))+list(p.glob('r*.startup')):
 dev=int(f.stem[2:]) if f.stem.startswith('pc') else None
 with f.open('a') as out:
  out.write(f'\\n# DNS lab resolver\\necho \"nameserver {ips[2]}\" > /etc/resolv.conf\\n')
  if dev in servers: out.write('systemctl restart named\\n')
print('Root pc1',ips[1],'resolver pc2',ips[2], 'zones',[(z,i,ips[i]) for z,i in zones.items()]); print('records',len(hosts),'MX',len(mx))
PY"

